dashboard.definition:
{
 "title": "Process Attribution",
 "description": "Which binary opened the connection: WFP audit events with a process to service map, LOLBin and rarity hunts, and listener detection.",
 "visualizations": {
  "hdr": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "## Process Attribution\n`pfirewall.log` tells you an address was contacted. Windows Filtering Platform audit events tell you **which binary** did it.\n\nNeeds Security events **5157** (blocked) and **5152** at minimum — add **5156** for allowed connections, but it is very verbose. Point the `wfo_wfp_index` macro at the index holding them.",
    "fontSize": "large",
    "fontColor": "#dbe0e6",
    "backgroundColor": "transparent"
   }
  },
  "kpi_total": {
   "type": "splunk.singlevalue",
   "title": "Connection events",
   "dataSources": {
    "primary": "ds_kpi"
   },
   "options": {
    "majorValue": "> primary | seriesByName('total') | lastPoint()",
    "backgroundColor": "transparent",
    "numberPrecision": 0,
    "majorColor": "#dbe0e6"
   },
   "showProgressBar": false,
   "showLastUpdated": false
  },
  "kpi_blocked": {
   "type": "splunk.singlevalue",
   "title": "Blocked",
   "dataSources": {
    "primary": "ds_kpi"
   },
   "options": {
    "majorValue": "> primary | seriesByName('blocked') | lastPoint()",
    "backgroundColor": "transparent",
    "numberPrecision": 0,
    "majorColor": "#e5484d"
   },
   "showProgressBar": false,
   "showLastUpdated": false
  },
  "kpi_processes": {
   "type": "splunk.singlevalue",
   "title": "Distinct binaries",
   "dataSources": {
    "primary": "ds_kpi"
   },
   "options": {
    "majorValue": "> primary | seriesByName('processes') | lastPoint()",
    "backgroundColor": "transparent",
    "numberPrecision": 0,
    "majorColor": "#a175ff"
   },
   "showProgressBar": false,
   "showLastUpdated": false
  },
  "kpi_hosts": {
   "type": "splunk.singlevalue",
   "title": "Hosts",
   "dataSources": {
    "primary": "ds_kpi"
   },
   "options": {
    "majorValue": "> primary | seriesByName('hosts') | lastPoint()",
    "backgroundColor": "transparent",
    "numberPrecision": 0,
    "majorColor": "#4fa3ff"
   },
   "showProgressBar": false,
   "showLastUpdated": false
  },
  "kpi_peers": {
   "type": "splunk.singlevalue",
   "title": "Peers",
   "dataSources": {
    "primary": "ds_kpi"
   },
   "options": {
    "majorValue": "> primary | seriesByName('peers') | lastPoint()",
    "backgroundColor": "transparent",
    "numberPrecision": 0,
    "majorColor": "#31c2c9"
   },
   "showProgressBar": false,
   "showLastUpdated": false
  },
  "kpi_ext": {
   "type": "splunk.singlevalue",
   "title": "External peers",
   "dataSources": {
    "primary": "ds_kpi"
   },
   "options": {
    "majorValue": "> primary | seriesByName('ext_peers') | lastPoint()",
    "backgroundColor": "transparent",
    "numberPrecision": 0,
    "majorColor": "#f5a623"
   },
   "showProgressBar": false,
   "showLastUpdated": false
  },
  "hdr_top": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "### Which binaries generate network traffic — click one to filter this page",
    "fontSize": "medium",
    "fontColor": "#dbe0e6",
    "backgroundColor": "transparent"
   }
  },
  "viz_graph": {
   "type": "splunk.networkGraph",
   "title": "Process to service map",
   "dataSources": {
    "primary": "ds_graph"
   },
   "options": {
    "layout": "hierarchical",
    "linkStyle": "s",
    "linkDirection": "one-way",
    "nodeColors": "#a175ff",
    "backgroundColor": "transparent",
    "nodeHorizontalPadding": 60,
    "linkValues": "> primary | seriesByName('linkValues')"
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "hideWhenNoData": true
  },
  "viz_top": {
   "type": "splunk.table",
   "title": "Top processes",
   "dataSources": {
    "primary": "ds_top"
   },
   "options": {
    "count": 12,
    "dataOverlayMode": "none",
    "backgroundColor": "transparent",
    "tableFormat": {
     "rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)"
    },
    "showRowNumbers": true
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "eventHandlers": [
    {
     "type": "drilldown.setToken",
     "options": {
      "tokens": [
       {
        "token": "tk_process",
        "key": "row.process_name.value"
       }
      ]
     }
    }
   ]
  },
  "viz_timechart": {
   "type": "splunk.area",
   "title": "Activity",
   "dataSources": {
    "primary": "ds_timechart"
   },
   "options": {
    "stackMode": "stacked",
    "seriesColors": [
     "#2fb67c",
     "#e5484d",
     "#8c9199"
    ],
    "legendDisplay": "bottom",
    "yAxisTitleText": "Events",
    "xAxisTitleText": "",
    "backgroundColor": "transparent"
   },
   "showProgressBar": false,
   "showLastUpdated": false
  },
  "hdr_hunt": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "### Hunting angles",
    "fontSize": "medium",
    "fontColor": "#dbe0e6",
    "backgroundColor": "transparent"
   }
  },
  "viz_trellis": {
   "type": "splunk.singlevalue",
   "title": "",
   "dataSources": {
    "primary": "ds_trellis"
   },
   "options": {
    "majorValue": "> primary | seriesByName('events') | lastPoint()",
    "backgroundColor": "transparent",
    "numberPrecision": 0,
    "majorColor": "#e5484d",
    "splitByLayout": "trellis",
    "trellisSplitBy": "process_name",
    "trellisMinColumnWidth": 200,
    "trellisRowHeight": 140,
    "trellisPageCount": 12
   },
   "showProgressBar": false,
   "showLastUpdated": false
  },
  "viz_lolbin": {
   "type": "splunk.table",
   "title": "Living-off-the-land binaries with network activity",
   "dataSources": {
    "primary": "ds_lolbin"
   },
   "options": {
    "count": 10,
    "dataOverlayMode": "none",
    "backgroundColor": "transparent",
    "tableFormat": {
     "rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)"
    },
    "showRowNumbers": true
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "description": "PowerShell, certutil, mshta, regsvr32 and friends. Legitimate on some hosts, a strong signal on most.",
   "eventHandlers": [
    {
     "type": "drilldown.customUrl",
     "options": {
      "url": "/app/windows_firewall_app/windows_firewall_host_view?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$&form.tk_host=$row.host.value$",
      "newTab": false
     }
    }
   ]
  },
  "viz_rare": {
   "type": "splunk.table",
   "title": "Binaries seen on one or two hosts only",
   "dataSources": {
    "primary": "ds_rare"
   },
   "options": {
    "count": 10,
    "dataOverlayMode": "none",
    "backgroundColor": "transparent",
    "tableFormat": {
     "rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)"
    },
    "showRowNumbers": true
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "description": "Rarity across the estate is the cheapest anomaly signal you have.",
   "eventHandlers": [
    {
     "type": "drilldown.linkToSearch",
     "options": {
      "type": "auto",
      "newTab": true
     }
    }
   ]
  },
  "hdr_ext": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "### Reaching outside",
    "fontSize": "medium",
    "fontColor": "#dbe0e6",
    "backgroundColor": "transparent"
   }
  },
  "viz_external": {
   "type": "splunk.table",
   "title": "Processes talking to external addresses",
   "dataSources": {
    "primary": "ds_external"
   },
   "options": {
    "count": 12,
    "dataOverlayMode": "none",
    "backgroundColor": "transparent",
    "tableFormat": {
     "rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)"
    },
    "showRowNumbers": true
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "eventHandlers": [
    {
     "type": "drilldown.linkToSearch",
     "options": {
      "type": "auto",
      "newTab": true
     }
    }
   ]
  },
  "viz_listen": {
   "type": "splunk.table",
   "title": "Processes binding or listening on a local port",
   "dataSources": {
    "primary": "ds_listen"
   },
   "options": {
    "count": 12,
    "dataOverlayMode": "none",
    "backgroundColor": "transparent",
    "tableFormat": {
     "rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)"
    },
    "showRowNumbers": true
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "description": "Needs events 5154/5155/5158/5159. A new listener on a workstation is rarely benign.",
   "eventHandlers": [
    {
     "type": "drilldown.linkToSearch",
     "options": {
      "type": "auto",
      "newTab": true
     }
    }
   ]
  }
 },
 "dataSources": {
  "ds_host_list": {
   "type": "ds.search",
   "options": {
    "query": "| tstats count WHERE index IN `windows_firewall_index` sourcetype=\"windows:pfirewall\" BY host | fields host | sort host"
   },
   "name": "Host list"
  },
  "ds_wfp": {
   "type": "ds.search",
   "options": {
    "query": "`wfo_wfp` | search host IN ($ms_host$) process_name=\"$tk_process$\" action IN ($ms_action$) | fields _time _raw host source sourcetype index action blocked blocked_pct connections dest_ip dest_port dest_scope dest_service events ext_peers external first_seen hosts linkValues local_port m operation peers ports process_name process_path processes scope service services src_port target total wfp_operation"
   },
   "name": "WFP base search"
  },
  "ds_kpi": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_wfp",
    "query": "| stats count AS total, count(eval(action=\"blocked\")) AS blocked, dc(process_name) AS processes, dc(host) AS hosts, dc(dest_ip) AS peers, dc(eval(if(dest_scope=\"external\", dest_ip, null()))) AS ext_peers"
   },
   "name": "KPI"
  },
  "ds_top": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_wfp",
    "query": "| stats count AS connections, count(eval(action=\"blocked\")) AS blocked, dc(host) AS hosts, dc(dest_ip) AS peers, dc(dest_port) AS ports, values(dest_service) AS services BY process_name | eval blocked_pct = round(blocked*100/connections, 1) | sort - connections | head 25"
   },
   "name": "Processes"
  },
  "ds_graph": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_wfp",
    "query": "| where dest_scope=\"external\" | eval service = coalesce(dest_service, \"port \".dest_port) | stats count AS linkValues BY process_name, service | rename process_name AS source, service AS target | sort - linkValues | head 70 | appendpipe [| stats count BY target | rename target AS source | fields source] | table source target linkValues"
   },
   "name": "Process to service graph"
  },
  "ds_timechart": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_wfp",
    "query": "| timechart span=10m count BY action"
   },
   "name": "Activity"
  },
  "ds_rare": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_wfp",
    "query": "| stats count AS connections, dc(host) AS hosts, values(dest_port) AS dest_port, values(process_path) AS process_path, min(_time) AS first_seen BY process_name | where hosts <= 2 | eval first_seen = strftime(first_seen, \"%F %T\") | sort + hosts, - connections | head 20"
   },
   "name": "Rare processes"
  },
  "ds_lolbin": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_wfp",
    "query": "| search process_name IN (\"powershell.exe\",\"pwsh.exe\",\"cmd.exe\",\"cscript.exe\",\"wscript.exe\",\"mshta.exe\",\"rundll32.exe\",\"regsvr32.exe\",\"certutil.exe\",\"bitsadmin.exe\",\"curl.exe\",\"wget.exe\",\"msiexec.exe\",\"installutil.exe\",\"msbuild.exe\",\"wmic.exe\",\"forfiles.exe\",\"ftp.exe\",\"odbcconf.exe\") | stats count AS connections, count(eval(action=\"blocked\")) AS blocked, dc(dest_ip) AS peers, values(dest_port) AS dest_port, values(dest_scope) AS scope BY host, process_name | sort - connections | head 25"
   },
   "name": "LOLBins"
  },
  "ds_external": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_wfp",
    "query": "| search dest_scope=external | stats count AS connections, dc(host) AS hosts, values(dest_service) AS service BY process_name, dest_ip, dest_port | sort - connections | head 25"
   },
   "name": "External destinations"
  },
  "ds_listen": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_wfp",
    "query": "| search wfp_operation IN (\"listen allowed\",\"listen blocked\",\"bind allowed\",\"bind blocked\",\"inbound accept blocked\") | stats count AS events, values(wfp_operation) AS operation, values(src_port) AS local_port, dc(host) AS hosts BY process_name | sort - events | head 20"
   },
   "name": "Listeners"
  },
  "ds_trellis": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_wfp",
    "query": "| stats count AS events BY process_name, action | where action=\"blocked\" | sort - events | head 12 | fields process_name events"
   },
   "name": "Blocked per process"
  }
 },
 "inputs": {
  "input_time": {
   "type": "input.timerange",
   "title": "Time range",
   "options": {
    "token": "global_time",
    "defaultValue": "-24h@h,now"
   }
  },
  "input_host": {
   "type": "input.multiselect",
   "title": "Host",
   "dataSources": {
    "primary": "ds_host_list"
   },
   "options": {
    "items": ">frame(label, value) | prepend(formattedStatics) | objects()",
    "token": "ms_host",
    "defaultValue": [
     "*"
    ],
    "valuePrefix": "\"",
    "valueSuffix": "\"",
    "delimiter": ","
   },
   "context": {
    "formattedConfig": {
     "number": {
      "prefix": ""
     }
    },
    "formattedStatics": ">statics | formatByType(formattedConfig)",
    "statics": [
     {
      "label": "All",
      "value": "*"
     }
    ],
    "label": ">primary | seriesByName(\"host\") | renameSeries(\"label\") | formatByType(formattedConfig)",
    "value": ">primary | seriesByName(\"host\") | renameSeries(\"value\") | formatByType(formattedConfig)"
   }
  },
  "input_process": {
   "type": "input.text",
   "title": "Process name",
   "options": {
    "token": "tk_process",
    "defaultValue": "*"
   }
  },
  "input_action": {
   "type": "input.multiselect",
   "title": "Action",
   "options": {
    "token": "ms_action",
    "defaultValue": [
     "*"
    ],
    "valuePrefix": "\"",
    "valueSuffix": "\"",
    "delimiter": ",",
    "items": [
     {
      "label": "All",
      "value": "*"
     },
     {
      "label": "Allowed",
      "value": "allowed"
     },
     {
      "label": "Blocked",
      "value": "blocked"
     }
    ]
   }
  }
 },
 "layout": {
  "tabs": {
   "items": [
    {
     "layoutId": "layout_map",
     "label": "Process map"
    },
    {
     "layoutId": "layout_hunt",
     "label": "Hunting"
    },
    {
     "layoutId": "layout_ext",
     "label": "Outbound & listeners"
    }
   ]
  },
  "layoutDefinitions": {
   "layout_map": {
    "type": "grid",
    "options": {
     "width": 1440,
     "submitButton": false,
     "backgroundColor": "#0e1319"
    },
    "structure": [
     {
      "item": "hdr",
      "type": "block",
      "position": {
       "x": 0,
       "y": 0,
       "w": 1440,
       "h": 140
      }
     },
     {
      "item": "kpi_total",
      "type": "block",
      "position": {
       "x": 0,
       "y": 140,
       "w": 240,
       "h": 150
      }
     },
     {
      "item": "kpi_blocked",
      "type": "block",
      "position": {
       "x": 240,
       "y": 140,
       "w": 240,
       "h": 150
      }
     },
     {
      "item": "kpi_processes",
      "type": "block",
      "position": {
       "x": 480,
       "y": 140,
       "w": 240,
       "h": 150
      }
     },
     {
      "item": "kpi_hosts",
      "type": "block",
      "position": {
       "x": 720,
       "y": 140,
       "w": 240,
       "h": 150
      }
     },
     {
      "item": "kpi_peers",
      "type": "block",
      "position": {
       "x": 960,
       "y": 140,
       "w": 240,
       "h": 150
      }
     },
     {
      "item": "kpi_ext",
      "type": "block",
      "position": {
       "x": 1200,
       "y": 140,
       "w": 240,
       "h": 150
      }
     },
     {
      "item": "hdr_top",
      "type": "block",
      "position": {
       "x": 0,
       "y": 290,
       "w": 1440,
       "h": 40
      }
     },
     {
      "item": "viz_graph",
      "type": "block",
      "position": {
       "x": 0,
       "y": 330,
       "w": 1440,
       "h": 460
      }
     },
     {
      "item": "viz_top",
      "type": "block",
      "position": {
       "x": 0,
       "y": 790,
       "w": 892,
       "h": 400
      }
     },
     {
      "item": "viz_timechart",
      "type": "block",
      "position": {
       "x": 892,
       "y": 790,
       "w": 548,
       "h": 400
      }
     }
    ]
   },
   "layout_hunt": {
    "type": "grid",
    "options": {
     "width": 1440,
     "submitButton": false,
     "backgroundColor": "#0e1319"
    },
    "structure": [
     {
      "item": "hdr_hunt",
      "type": "block",
      "position": {
       "x": 0,
       "y": 0,
       "w": 1440,
       "h": 40
      }
     },
     {
      "item": "viz_trellis",
      "type": "block",
      "position": {
       "x": 0,
       "y": 40,
       "w": 1440,
       "h": 300
      }
     },
     {
      "item": "viz_lolbin",
      "type": "block",
      "position": {
       "x": 0,
       "y": 340,
       "w": 720,
       "h": 380
      }
     },
     {
      "item": "viz_rare",
      "type": "block",
      "position": {
       "x": 720,
       "y": 340,
       "w": 720,
       "h": 380
      }
     }
    ]
   },
   "layout_ext": {
    "type": "grid",
    "options": {
     "width": 1440,
     "submitButton": false,
     "backgroundColor": "#0e1319"
    },
    "structure": [
     {
      "item": "hdr_ext",
      "type": "block",
      "position": {
       "x": 0,
       "y": 0,
       "w": 1440,
       "h": 40
      }
     },
     {
      "item": "viz_external",
      "type": "block",
      "position": {
       "x": 0,
       "y": 40,
       "w": 792,
       "h": 440
      }
     },
     {
      "item": "viz_listen",
      "type": "block",
      "position": {
       "x": 792,
       "y": 40,
       "w": 648,
       "h": 440
      }
     }
    ]
   }
  },
  "globalInputs": [
   "input_time",
   "input_host",
   "input_process",
   "input_action"
  ]
 },
 "defaults": {
  "dataSources": {
   "ds.search": {
    "options": {
     "queryParameters": {
      "earliest": "$global_time.earliest$",
      "latest": "$global_time.latest$"
     }
    }
   }
  }
 }
}
